function ConflictCard({ conflict, onClick }) {
  const isAvailable = conflict.available;
  return (
    <button
      onClick={() => isAvailable && onClick(conflict)}
      disabled={!isAvailable}
      style={{
        position: "relative",
        textAlign: "left",
        background: isAvailable ? "rgba(244,234,213,0.03)" : "rgba(244,234,213,0.01)",
        border: `1px solid ${isAvailable ? "rgba(212,175,55,0.3)" : "rgba(212,175,55,0.1)"}`,
        borderRadius: 2,
        padding: "28px 32px",
        cursor: isAvailable ? "pointer" : "not-allowed",
        opacity: isAvailable ? 1 : 0.45,
        color: "#f4ead5",
        fontFamily: '"Cormorant Garamond", "Noto Serif KR", serif',
        transition: "all 0.3s",
        overflow: "hidden",
      }}
      onMouseEnter={(e) => { if (isAvailable) { e.currentTarget.style.background = "rgba(212,175,55,0.08)"; e.currentTarget.style.borderColor = "#d4af37"; e.currentTarget.style.transform = "translateY(-2px)"; } }}
      onMouseLeave={(e) => { if (isAvailable) { e.currentTarget.style.background = "rgba(244,234,213,0.03)"; e.currentTarget.style.borderColor = "rgba(212,175,55,0.3)"; e.currentTarget.style.transform = "translateY(0)"; } }}
    >
      {!isAvailable && (
        <div style={{
          position: "absolute", top: 12, right: 12,
          fontSize: 9, letterSpacing: "0.2em", color: "rgba(244,234,213,0.5)",
          fontFamily: "system-ui, sans-serif", padding: "3px 8px",
          border: "1px solid rgba(244,234,213,0.2)", borderRadius: 2,
        }}>
          준비 중
        </div>
      )}
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
        <div style={{ fontSize: 32 }}>{conflict.flag}</div>
        <div>
          <div style={{ fontSize: 9, letterSpacing: "0.3em", color: "rgba(212,175,55,0.7)", fontFamily: "system-ui, sans-serif", marginBottom: 2 }}>
            {conflict.type.toUpperCase()}
          </div>
          <div style={{ fontSize: 10, letterSpacing: "0.15em", color: "rgba(244,234,213,0.55)", fontFamily: "system-ui, sans-serif" }}>
            {conflict.actors}인 인터뷰 가능
          </div>
        </div>
      </div>
      <h3 style={{ fontSize: 22, fontWeight: 400, margin: "0 0 4px", letterSpacing: "0" }}>
        {conflict.nameKo}
      </h3>
      <div style={{ fontSize: 12, color: "rgba(244,234,213,0.5)", fontStyle: "italic", marginBottom: 14, fontFamily: "system-ui, sans-serif" }}>
        {conflict.nameEn}
      </div>
      <div style={{ fontSize: 11, letterSpacing: "0.05em", color: "#d4af37", marginBottom: 12, fontFamily: "system-ui, sans-serif" }}>
        {conflict.period} · {conflict.region}
      </div>
      <div style={{ width: 30, height: 1, background: "rgba(212,175,55,0.3)", marginBottom: 12 }} />
      <p style={{ fontSize: 13, lineHeight: 1.6, color: "rgba(244,234,213,0.75)", margin: 0 }}>
        {conflict.summary}
      </p>
    </button>
  );
}

